args<-commandArgs(trailingOnly=TRUE);r<-normalizePath(args[1]);base<-normalizePath(args[2]);out<-file.path(r,'audit/math_fixture_PRIVATE');dir.create(out);suppressPackageStartupMessages({library(dplyr);library(reshape2);library(spdep);library(sp)});set.seed(2026110709);fq<-read.delim(file.path(base,'inputs/frequency_PRIVATE.tsv'),row.names=1,check.names=FALSE);nodes<-rownames(fq);a<-matrix(rexp(100*length(nodes)),100,length(nodes),dimnames=list(sprintf('synthetic%03d',1:100),nodes));coords<-cbind(runif(100),runif(100));ref<-list(filter=read.delim(file.path(base,'CM_results/CM_members_after_author_network_filter.tsv')));defs<-parse(file.path(r,'author/CoVarNet.R'));e<-new.env(parent=globalenv())
for(name in c('colocalization','bvMoranI')){i<-which(vapply(defs,function(x)is.call(x)&&length(x)>=3&&identical(x[[2]],as.name(name)),logical(1)));eval(defs[[i]],e)}
col<-e$colocalization(a,ref);mor<-e$bvMoranI(coords,a,ref);write.table(col,file.path(out,'coloc.tsv'),sep='\t',row.names=FALSE,quote=FALSE);write.table(mor,file.path(out,'moran.tsv'),sep='\t',row.names=FALSE,quote=FALSE);write.table(a,file.path(out,'abundance.tsv'),sep='\t',col.names=NA,quote=FALSE);nb<-spdep::knn2nb(spdep::knearneigh(coords,k=60));w<-spdep::nb2listwdist(nb,sp::SpatialPoints(coords),type='idw',style='W',alpha=2);edges<-do.call(rbind,lapply(seq_along(w$neighbours),function(i)data.frame(i=i,j=w$neighbours[[i]],weight=w$weights[[i]])));write.table(edges,file.path(out,'weights.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
